// J2 — contract → provider plan + conformance (SPEC §3, the headline seam).
//
// The payoff of the language-neutral deployment contract: a project generated by ANY
// published generator produces a contract that the published providers act on, with no
// per-language code. This journey takes a real deploymentContract from each published
// generator, feeds it to each published provider (supports + plan), runs both providers
// through the published `runProviderConformanceSuite`, and `tofu validate`s the IaC the
// AWS provider emits. All in-process against @latest — no cloud, no credentials, plan-only.
import { writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { journey, sh, assert, batch, hasTool, skip, tmpDir } from '../lib/harness.mjs';

const REPO = { owner: 'PackkitLabs', name: 'demo' };

// Acquire a real deploymentContract from each published generator (the generator half
// of the seam). Kept lazy so a generator that fails to load fails only its own checks.
async function contracts() {
	const js = await import('create-packkit/embedded');
	const py = await import('create-packkit-py');
	const go = await import('create-packkit-go');
	return {
		static: js.packkitGenerator.createProject({ preset: 'react-app', name: 'demo' })
			.deploymentContract,
		service: py.pythonGenerator.createProject({ preset: 'py-service', name: 'demo' })
			.deploymentContract,
		worker: go.goGenerator.createProject({ preset: 'go-worker', name: 'demo' }).deploymentContract,
	};
}

function assertPlan(plan, providerId) {
	assert(plan && typeof plan === 'object', 'plan is not an object');
	assert(plan.provider === providerId, `plan.provider is "${plan.provider}", expected "${providerId}"`);
	assert(
		Number.isInteger(plan.schemaVersion) && plan.schemaVersion >= 1,
		`plan.schemaVersion is not a positive integer (${plan.schemaVersion})`,
	);
	// Must survive a JSON round-trip (the provider-conformance rule, checked here on real input).
	JSON.parse(JSON.stringify(plan));
}

// Execute the published provider-conformance suite immediately (no test framework): the
// register callback just runs each check and throws on failure.
function runConformance(runSuite, harness) {
	runSuite(harness, (_name, fn) => fn());
}

journey('j2', 'contract → provider plan + conformance', async () => {
	const b = batch();
	const c = await contracts();
	const { createAwsProvider } = await import('@packkit/provider-aws');
	const { createNetlifyProvider } = await import('@packkit/provider-netlify');
	const { runProviderConformanceSuite } = await import('@packkit/core/testing');
	const aws = createAwsProvider();
	const netlify = createNetlifyProvider();

	// --- AWS: static (S3+CloudFront), service (App Runner), worker (Fargate) -------------
	for (const [archetype, contract] of Object.entries(c)) {
		await b.run(`aws supports the ${archetype} contract from its generator`, () => {
			const res = aws.supports(contract);
			assert(res.supported, `aws rejected ${archetype}: ${JSON.stringify(res.reasons)}`);
		});
		await b.run(`aws plans the ${archetype} contract`, () => {
			const plan = aws.plan({
				project: { deploymentContract: contract },
				options: { name: 'demo', region: 'us-east-1', repository: REPO },
			});
			assertPlan(plan, 'aws');
		});
	}

	// --- Netlify: static only; must reason-reject non-static -----------------------------
	await b.run('netlify supports the static contract from create-packkit', () => {
		const res = netlify.supports(c.static);
		assert(res.supported, `netlify rejected static: ${JSON.stringify(res.reasons)}`);
	});
	await b.run('netlify plans the static contract', () => {
		const plan = netlify.plan({
			project: { deploymentContract: c.static },
			repository: REPO,
		});
		assertPlan(plan, 'netlify');
	});
	await b.run('netlify reason-rejects a service contract (not just false)', () => {
		const res = netlify.supports(c.service);
		assert(!res.supported, 'netlify unexpectedly supported a service contract');
		assert(res.reasons?.length && res.reasons[0].code, 'rejection carried no reason code');
	});

	// --- Both providers pass the published provider-conformance suite --------------------
	await b.run('provider-aws passes runProviderConformanceSuite', () => {
		runConformance(runProviderConformanceSuite, {
			provider: aws,
			supportedContract: c.static,
			unsupportedContract: { type: 'library' },
			planInput: () => ({
				project: { deploymentContract: c.static },
				options: { name: 'demo', region: 'us-east-1', repository: REPO },
			}),
			secrets: ['AKIAIOSFODNN7EXAMPLE'],
		});
	});
	await b.run('provider-netlify passes runProviderConformanceSuite', () => {
		runConformance(runProviderConformanceSuite, {
			provider: netlify,
			supportedContract: c.static,
			unsupportedContract: { type: 'service' },
			planInput: () => ({ project: { deploymentContract: c.static }, repository: REPO }),
			secrets: ['nfp_deadbeefdeadbeefdeadbeef'],
		});
	});

	// --- The AWS IaC the provider emits is valid OpenTofu -------------------------------
	await b.run('aws-emitted OpenTofu validates (static archetype)', () => {
		if (!hasTool('tofu', ['version'])) skip('tofu not on PATH');
		const prepared = aws.prepare({
			project: { deploymentContract: c.static },
			options: { name: 'demo', region: 'us-east-1', repository: REPO },
		});
		const dir = tmpDir('packkit-e2e-tofu-');
		for (const [rel, body] of Object.entries(prepared.files)) {
			const abs = join(dir, rel);
			mkdirSync(dirname(abs), { recursive: true });
			writeFileSync(abs, body);
		}
		const infra = join(dir, 'infra');
		sh('tofu', ['init', '-backend=false', '-input=false'], { cwd: infra });
		sh('tofu', ['validate'], { cwd: infra });
	});

	b.done();
});
